//! Pass-through for every export of the real DLL in the system folder (`winmm.dll` or
//! `version.dll` builds). Once this file is loaded, every module in the game that imports that
//! name gets these exports, not just NMS.exe, so the list is the complete System32 export table
//! (`exports\<name>.txt`, written by `py -3 release.py proxy-exports`).
//!
//! Each export is a two-instruction stub (`mov eax, <index>; jmp fwd_common`) generated by
//! `build.rs`. The first call of an export loads the real DLL by full path and looks the export
//! up; later calls jump straight through its slot. Nothing happens in DllMain. Argument
//! registers (RCX, RDX, R8, R9, XMM0-3) and the stack are untouched on the way, so any signature
//! passes through. An export the real DLL lacks returns 0.

use std::sync::atomic::{AtomicUsize, Ordering};

use windows_sys::Win32::System::LibraryLoader::{GetProcAddress, LoadLibraryW};
use windows_sys::Win32::System::SystemInformation::GetSystemDirectoryW;

pub(crate) enum Export {
    /// NUL-terminated export name.
    Name(&'static [u8]),
    /// Exported by ordinal only (winmm.dll has one, version.dll none).
    #[allow(dead_code)]
    Ordinal(u16),
}

include!(concat!(env!("OUT_DIR"), "/forward_gen.rs"));

static REAL: AtomicUsize = AtomicUsize::new(0);

/// `<system folder>\<DLL>`, loaded on the first forwarded call. No lock: two threads may both call
/// LoadLibraryW (the second only raises the reference count), so a thread that holds the loader
/// lock never waits on one that needs it.
fn real() -> usize {
    let loaded = REAL.load(Ordering::Acquire);
    if loaded != 0 {
        return loaded;
    }
    let mut path = [0u16; 300];
    // SAFETY: the length passed matches the buffer.
    let n = unsafe { GetSystemDirectoryW(path.as_mut_ptr(), 260) } as usize;
    let name: Vec<u16> = format!("\\{DLL}\0").encode_utf16().collect();
    if n == 0 || n >= 260 || n + name.len() > path.len() {
        return 0;
    }
    path[n..n + name.len()].copy_from_slice(&name);
    // SAFETY: NUL-terminated absolute path, so this never finds this file again.
    let module = unsafe { LoadLibraryW(path.as_ptr()) } as usize;
    if module != 0 {
        REAL.store(module, Ordering::Release);
    }
    module
}

/// Address of export `index` in the real DLL, or 0. Called from `fwd_slow`; never panics.
extern "system" fn resolve(index: u32) -> usize {
    let (Some(export), Some(slot)) = (EXPORTS.get(index as usize), SLOTS.get(index as usize)) else {
        return 0;
    };
    let module = real();
    if module == 0 {
        return 0;
    }
    let name = match export {
        Export::Name(name) => name.as_ptr(),
        // An ordinal goes in the low word of the name pointer (MAKEINTRESOURCE).
        Export::Ordinal(ordinal) => *ordinal as usize as *const u8,
    };
    // SAFETY: a module handle from LoadLibraryW and a NUL-terminated name or an ordinal.
    let address = unsafe { GetProcAddress(module as _, name) }.map_or(0, |f| f as usize);
    if address != 0 {
        slot.store(address, Ordering::Release);
    }
    address
}

/// EAX = export index. A resolved slot is a tail jump; otherwise `fwd_slow`.
/// Only RAX, R10 and R11 change (volatile and never arguments in the x64 calling convention).
#[unsafe(naked)]
unsafe extern "C" fn fwd_common() {
    core::arch::naked_asm!(
        "lea r11, [rip + {slots}]",
        "mov r10, qword ptr [r11 + rax*8]",
        "test r10, r10",
        "jz {slow}",
        "jmp r10",
        slots = sym SLOTS,
        slow = sym fwd_slow,
    )
}

/// Save the argument registers, resolve, restore them and jump to the real export. If it cannot
/// be found, return 0 to the caller. Entry RSP is 8 mod 16; 4 pushes and 0x68 bring it to 0 mod 16.
#[unsafe(naked)]
unsafe extern "C" fn fwd_slow() {
    core::arch::naked_asm!(
        ".seh_proc {me}",
        "push rcx",
        ".seh_pushreg rcx",
        "push rdx",
        ".seh_pushreg rdx",
        "push r8",
        ".seh_pushreg r8",
        "push r9",
        ".seh_pushreg r9",
        "sub rsp, 0x68",
        ".seh_stackalloc 0x68",
        ".seh_endprologue",
        "movdqu xmmword ptr [rsp+0x20], xmm0",
        "movdqu xmmword ptr [rsp+0x30], xmm1",
        "movdqu xmmword ptr [rsp+0x40], xmm2",
        "movdqu xmmword ptr [rsp+0x50], xmm3",
        "mov ecx, eax",
        "call {resolve}",
        "movdqu xmm0, xmmword ptr [rsp+0x20]",
        "movdqu xmm1, xmmword ptr [rsp+0x30]",
        "movdqu xmm2, xmmword ptr [rsp+0x40]",
        "movdqu xmm3, xmmword ptr [rsp+0x50]",
        "add rsp, 0x68",
        "pop r9",
        "pop r8",
        "pop rdx",
        "pop rcx",
        "test rax, rax",
        "jz 2f",
        "jmp rax",
        "2:",
        "ret",
        ".seh_endproc",
        me = sym fwd_slow,
        resolve = sym resolve,
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn export_table_matches_the_stub_count() {
        assert_eq!(EXPORTS.len(), SLOTS.len());
        assert!(EXPORTS.iter().all(|e| match e {
            Export::Name(n) => n.len() > 1 && n.ends_with(b"\0"),
            Export::Ordinal(o) => *o > 0,
        }));
    }

    /// `resolve` finds the real System32 export and fills its slot; an index past the end is 0.
    /// (`dev\test_proxy_variants.py` calls the stubs of the built DLL.)
    #[test]
    fn resolve_fills_the_slot() {
        let name: &[u8] = if DLL == "winmm.dll" { b"timeGetTime\0" } else { b"GetFileVersionInfoSizeW\0" };
        let index = EXPORTS.iter().position(|e| matches!(e, Export::Name(n) if *n == name)).expect("export in the list");
        assert_ne!(resolve(index as u32), 0);
        assert_ne!(SLOTS[index].load(Ordering::Acquire), 0);
        assert_eq!(resolve(EXPORTS.len() as u32), 0);
    }
}
